def _read_at(self, d,
                 interpolation='linear',
                 index=False,
                 return_basis=False):
        """
        Private function. Implements read_at() for a single depth.

        Args:
            d (float)
            interpolation (str)
            index(bool)
            return_basis (bool)

        Returns:
            float
        """
        if d in self.depths:
            if return_basis:
                return self.depths[self.depths.index(d)], self.data[self.depths.index(d)]
            else:
                return self.data[self.depths.index(d)]
        else:
            if interpolation == 'linear':
                if d < min(self.depths):
                    return self.data[0]
                elif d > max(self.depths):
                    return self.data[-1]
                else:
                    idx = (np.abs(self.depths - d)).argmin()
                    return (self.data[idx] + (self.data[idx+1] - self.data[idx]) * (d - self.depths[idx]) /
                            (self.depths[idx+1] - self.depths[idx]))
            elif interpolation == 'nearest':
                if d < min(self.depths):
                    return self.data[0]
                elif d > max(self.depths):
                    return self.data[-1]
                else:
                    idx = (np.abs(self.depths - d)).argmin()
                    return self.data[idx]
            else:
                raise ValueError('Interpolation type not recognized.')

